//! Telling generated files apart, so the index skips them.

/// How much of a file's start is searched for a generated-code marker.
const HEAD_BYTES: usize = 2048;
const HEAD_LINES: usize = 10;

/// Files at least this large whose lines average at least [`MINIFIED_LINE`] bytes are minified.
const MINIFIED_SIZE: usize = 2048;
const MINIFIED_LINE: usize = 300;

/// Whether a path names a generated file: minified JavaScript, by its name.
pub(crate) fn path_is_generated(path: &str) -> bool {
    let name = path.rsplit('/').next().unwrap_or(path);
    [".min.js", ".min.mjs", ".min.cjs"]
        .iter()
        .any(|suffix| name.ends_with(suffix))
}

/// Whether a file's contents are generated: a marker near the top, as code generators write
/// (`// Code generated … DO NOT EDIT.`, `@generated`, "automatically generated"), or lines far
/// longer than people write, as in minified code.
pub(crate) fn contents_are_generated(contents: &[u8]) -> bool {
    has_marker(head(contents)) || is_minified(contents)
}

/// The first lines of a file, up to [`HEAD_LINES`] or [`HEAD_BYTES`].
fn head(contents: &[u8]) -> &[u8] {
    let contents = &contents[..contents.len().min(HEAD_BYTES)];
    let end = contents
        .iter()
        .enumerate()
        .filter(|(_, byte)| **byte == b'\n')
        .nth(HEAD_LINES - 1)
        .map_or(contents.len(), |(index, _)| index);
    &contents[..end]
}

fn has_marker(head: &[u8]) -> bool {
    let head = head.to_ascii_lowercase();
    let contains = |needle: &str| {
        head.windows(needle.len())
            .any(|window| window == needle.as_bytes())
    };
    contains("@generated")
        || contains("autogenerated")
        || contains("auto-generated")
        || contains("automatically generated")
        || (contains("generated") && contains("do not edit"))
}

fn is_minified(contents: &[u8]) -> bool {
    let lines = contents.iter().filter(|byte| **byte == b'\n').count() + 1;
    contents.len() >= MINIFIED_SIZE && contents.len() / lines >= MINIFIED_LINE
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn minified_javascript_is_generated_by_its_name() {
        assert!(path_is_generated("vendor/jquery.min.js"));
        assert!(path_is_generated("lib.min.mjs"));
        assert!(!path_is_generated("src/admin.js"));
        assert!(!path_is_generated("min.js/index.ts"));
    }

    #[test]
    fn markers_count_only_near_the_top() {
        let late = format!(
            "{}// DO NOT EDIT: generated\n",
            "fn a() {}\n".repeat(HEAD_LINES)
        );
        assert!(!contents_are_generated(late.as_bytes()));

        let early = format!(
            "// Code generated by stringer. DO NOT EDIT.\n{}",
            "fn a() {}\n".repeat(20)
        );
        assert!(contents_are_generated(early.as_bytes()));
    }

    #[test]
    fn do_not_edit_alone_isnt_a_marker() {
        assert!(!contents_are_generated(
            b"// Do not edit without updating the docs.\nfn a() {}\n"
        ));
        assert!(contents_are_generated(
            b"# Generated by the protocol buffer compiler.  DO NOT EDIT!\n"
        ));
    }

    #[test]
    fn long_lines_in_a_small_file_arent_minified() {
        let line = format!("const data = \"{}\";\n", "x".repeat(1000));
        assert!(!contents_are_generated(line.as_bytes()));
        assert!(contents_are_generated(line.repeat(3).as_bytes()));
    }
}
